std::size_t total_partitions = static_cast<std::size_t>(num_buckets) * static_cast<std::size_t>(partitions_per_bucket);
if (total_partitions == 0) {
    return std::make_unique<std::map<float, BucketPtr>>();
}
float step = 1.0f / static_cast<float>(total_partitions);

buckets_out.clear();
buckets_out.reserve(num_buckets);

for (int i = 0; i < num_buckets; ++i) {
    std::vector<float> points;
    points.reserve(partitions_per_bucket);
    for (int k = 0; k < partitions_per_bucket; ++k) {
        std::size_t idx = static_cast<std::size_t>(i) + static_cast<std::size_t>(k) * static_cast<std::size_t>(num_buckets);
        float pt = static_cast<float>(idx) * step;
        points.push_back(pt);
    }
    auto bucket = std::make_shared<Bucket>("bucket_" + std::to_string(i), std::move(points));
    buckets_out.push_back(bucket);
}

auto partition_map = std::make_unique<std::map<float, BucketPtr>>();
for (const auto& bucket_ptr : buckets_out) {
    for (float pt : bucket_ptr->partition_points()) {
        (*partition_map)[pt] = bucket_ptr;
    }
}
return partition_map;

